'use strict';
const ATLAS_SAVE_PREFIX='transit-atlas-map-',ATLAS_BEST='transit-atlas-best-v1';
let atlasSelected=activeAtlasMap?.id||'east',atlasMenuOpen=false,atlasRestart=false,atlasWasPaused=true,atlasScrollFrame=0;
function atlasSaveKey(id){return ATLAS_SAVE_PREFIX+(id||'legacy')+'-v1';}
function atlasSaved(id){try{let s=JSON.parse(localStorage.getItem(atlasSaveKey(id)));return s?.version===1&&s.economyVersion===6&&s.mapId===id?s:null;}catch{return null;}}
function atlasBest(){try{return JSON.parse(localStorage.getItem(ATLAS_BEST))||{};}catch{return {};}}
const saveBeforeAtlas=save;
save=function(){saveBeforeAtlas();try{if(!S)return;localStorage.setItem(atlasSaveKey(S.mapId),JSON.stringify(S));let best=atlasBest(),id=S.mapId||'legacy';best[id]=Math.max(best[id]||0,Math.floor(S.day));localStorage.setItem(ATLAS_BEST,JSON.stringify(best));return true;}catch{return false;}};
const loadBeforeAtlas=load;
load=function(){clearAtlasTransient();let ok=loadBeforeAtlas();if(ok){activateAtlasGeometry(S.mapId);configureGrowth();atlasMapCaption();}return ok;};
function atlasMapCaption(){let id=S?.mapId,meta=ATLAS_MAPS[id];let label=$('atlas-header-name');if(label)label.textContent=meta?(id==='east'?'东部':'西部'):'东岸';let cap=document.querySelector('.map-caption');if(cap)cap.innerHTML='<span class="eyebrow">'+(meta?meta.name:'原海岸存档')+'</span><span>'+(id==='east'?'平原河网 · 四季通行':id==='west'?'盆地河谷 · 山口相连':'沿海平原 · 河谷 · 北岭')+'</span>';}
function atlasThumbnail(id){let m=ATLAS_MAPS[id],colors=id==='east'?['#e4edcf','#afc5a0']:['#e3e9d5','#91a88f'];let s='<svg viewBox="-1000 -300 2200 1500" role="img" aria-label="'+m.name+'地形预览"><rect x="-1000" y="-300" width="2200" height="1500" fill="'+colors[0]+'"/>';
 for(let e of m.hills)s+='<ellipse cx="'+e.x+'" cy="'+e.y+'" rx="'+e.rx+'" ry="'+e.ry+'" fill="#c3d3aa"/>';
 for(let e of m.mountains)s+='<path d="M'+(e.x-e.rx)+','+(e.y+e.ry*.6)+' L'+(e.x-e.rx*.3)+','+(e.y-e.ry)+' L'+(e.x+e.rx*.3)+','+(e.y-e.ry*.3)+' L'+(e.x+e.rx)+','+(e.y+e.ry*.5)+' Z" fill="'+colors[1]+'"/>';
 for(let pts of [m.main,...m.branches])s+='<polyline points="'+pts.map(p=>p.join(',')).join(' ')+'" fill="none" stroke="#78afb3" stroke-width="25" stroke-linecap="round" stroke-linejoin="round"/>';
 // Sample the actual starting triangle; no fixed candidate city sites are exposed.
 let pts=m.start;s+='<polyline points="'+pts.map(p=>p.join(',')).join(' ')+'" fill="none" stroke="#c78057" stroke-width="14"/>';for(let [i,p] of pts.entries())s+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="25" fill="#fcfcf0" stroke="'+COLORS[i]+'" stroke-width="12"/>';return s+'</svg>';}
function atlasRefreshCards(){let best=atlasBest();for(let id of ['east','west']){let c=$('atlas-card-'+id),saved=atlasSaved(id);c?.classList.toggle('is-selected',id===atlasSelected);c?.setAttribute('aria-current',id===atlasSelected?'true':'false');let stat=$('atlas-best-'+id);if(stat)stat.textContent=best[id]?best[id]+' 天':'尚无记录';let note=$('atlas-save-'+id);if(note)note.textContent=atlasRestart?'开启新的旅程':saved?.lives>0&&saved.day>=1?'已有第 '+Math.floor(saved.day)+' 天存档 · 开始时继续':'从三座小城开始';$('atlas-dot-'+id)?.classList.toggle('active',id===atlasSelected);}let n=$('atlas-position');if(n)n.textContent=atlasSelected==='east'?'01 / 02':'02 / 02';}
function atlasSelect(id,scroll=true){atlasSelected=id;atlasRefreshCards();if(scroll){let rail=$('atlas-rail'),c=$('atlas-card-'+id);if(rail&&c)rail.scrollTo({left:c.offsetLeft-(rail.clientWidth-c.clientWidth)/2,behavior:'smooth'});}}
function showAtlasMaps(restart=false){atlasRestart=restart;atlasWasPaused=S.paused;S.paused=true;save();hideJunction();selected=null;$('details').hidden=true;draft=null;bridgeDraft=null;gesture=null;pointers.clear();$('drawbar').hidden=true;closeModal();atlasMenuOpen=true;$('map-selection').hidden=false;document.body.classList.add('atlas-selecting');atlasSelected=S.mapId||atlasSelected;atlasRefreshCards();requestAnimationFrame(()=>atlasSelect(atlasSelected));updateUI();}
function hideAtlasMaps(resume=false){atlasMenuOpen=false;$('map-selection').hidden=true;document.body.classList.remove('atlas-selecting');S.paused=resume?atlasWasPaused:true;updateUI();}
function startAtlasMap(){let id=atlasSelected;if(id===S.mapId&&!atlasRestart&&S.lives>0){hideAtlasMaps();closeModal();S.paused=false;atlasMapCaption();fit();save();updateUI();return;}let existing=atlasSaved(id);if(save()===false){toast('设备存储空间不足，暂时无法安全切换存档');return;}activateAtlasGeometry(id);if(!atlasRestart&&existing?.lives>0){try{localStorage.setItem('transit-atlas-v1',JSON.stringify(existing));}catch{activateAtlasGeometry(S.mapId);toast('存档写入失败，请稍后重试');return;}if(!load())reset();}else reset();configureGrowth();hideAtlasMaps();closeModal();S.paused=false;atlasMapCaption();fit();save();updateUI();toast(S.day>0?'已继续 '+ATLAS_MAPS[id].name+' · 第'+Math.floor(S.day)+'天':'从一座城市拖向另一座，查看报价后建设第一条线');}
welcome=function(){showAtlasMaps(false);};
newGame=function(){showAtlasMaps(true);};
const atlasOldGameover=gameover;
gameover=function(){save();openModal('<span class="eyebrow">旅程结算 · '+escapeHTML(ATLAS_MAPS[S.mapId]?.name||'东岸')+'</span><h1>谢谢你的连接。</h1><p>网络坚持了 '+Math.floor(S.day)+' 天，送达 '+S.delivered+' 位旅客。</p><div class="ux-actions"><button class="primary" onclick="showAtlasMaps(true)">重新选择地图</button><button onclick="closeModal()">查看交通网络</button></div>');};
// Portrait-first: do not request a landscape orientation lock.
syncOrientation=function(){let h=$('orientation-hint');if(h)h.hidden=true;};
async function enterAtlasFullscreen(){try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen?.();else await document.exitFullscreen?.();}catch{}resize();}
$('fullscreen').onclick=enterAtlasFullscreen;
$('atlas-menu').onclick=()=>showAtlasMaps(false);
const atlasHelpBefore=help;
help=function(){atlasHelpBefore();$('modal-content').innerHTML+='<section class="infra-card"><h3>东部与西部 · 1.1双地图更新</h3><p>选图时左右滑动卡片，右下角开始游戏。两图存档与最高天数分别保存，选择已有存档会继续。</p><p>当前城市群先逐步形成，再发现下一城市群；零散远镇客流较低，不产生新圈奖励。没有人口每日上限，也不会定时清除积压旅客。</p><button onclick="showAtlasMaps(false)">返回选图</button> <button onclick="showAtlasMaps(true)">选择地图重新开局</button></section>';if(localStorage.getItem(atlasSaveKey(null)))$('modal-content').innerHTML+='<section class="infra-card"><button onclick="resumeLegacyAtlas()">继续原海岸存档</button></section>';};$('help').onclick=()=>help();
(function initializeAtlasMenu(){let el=document.createElement('section');el.id='map-selection';el.className='map-selection';el.hidden=true;el.setAttribute('aria-label','选择地图');el.innerHTML=`<div class="atlas-top"><button id="atlas-back" class="atlas-back" aria-label="返回当前地图">←</button><span>交通线 <i>TRANSIT ATLAS</i></span><small id="atlas-position">01 / 02</small></div><div class="atlas-heading"><span class="eyebrow">选择一片土地</span><h1>让城市，彼此相连。</h1><p>左右滑动，选择你的下一段旅程。</p></div><div class="atlas-track-line" aria-hidden="true"></div><div id="atlas-rail" class="atlas-rail" tabindex="0" aria-label="左右滑动选择地图">${['east','west'].map((id,i)=>`<article id="atlas-card-${id}" class="atlas-card" data-map="${id}" aria-current="${i===0}"><div class="atlas-card-top"><span>MAP / 0${i+1}</span><b>${id==='east'?'平原 · 河网':'盆地 · 河谷'}</b></div><h2>${id==='east'?'东部':'西部'}</h2><div class="atlas-palette" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><div class="atlas-terrain">${atlasThumbnail(id)}</div><p>${id==='east'?'河流穿过开阔平原。<br>从小镇出发，让网络向远方延伸。':'沿河谷连接盆地。<br>穿越山口，为每一段旅途找到去路。'}</p><div class="atlas-record"><span>最高存活<b id="atlas-best-${id}">尚无记录</b></span><span class="atlas-medal" aria-hidden="true">↗</span></div><small id="atlas-save-${id}" class="atlas-save"></small></article>`).join('')}</div><div class="atlas-bottom"><div class="atlas-pagination"><button id="atlas-prev" aria-label="上一张地图">←</button><button id="atlas-dot-east" class="atlas-dot active" aria-label="选择东部"></button><button id="atlas-dot-west" class="atlas-dot" aria-label="选择西部"></button><button id="atlas-next" aria-label="下一张地图">→</button></div><button id="atlas-start" class="atlas-start">开始游戏 <span>↗</span></button></div>`;document.body.appendChild(el);
 $('atlas-back').onclick=()=>hideAtlasMaps(true);$('atlas-start').onclick=startAtlasMap;
 for(let id of ['east','west']){$('atlas-card-'+id).onclick=()=>atlasSelect(id);$('atlas-dot-'+id).onclick=()=>atlasSelect(id);}
 $('atlas-prev').onclick=()=>atlasSelect('east');$('atlas-next').onclick=()=>atlasSelect('west');
 let rail=$('atlas-rail');rail.addEventListener('scroll',()=>{if(atlasScrollFrame)return;atlasScrollFrame=requestAnimationFrame(()=>{atlasScrollFrame=0;let mid=rail.scrollLeft+rail.clientWidth/2;let cards=['east','west'].map(id=>({id,d:Math.abs($('atlas-card-'+id).offsetLeft+$('atlas-card-'+id).clientWidth/2-mid)}));atlasSelect(cards.sort((a,b)=>a.d-b.d)[0].id,false);});},{passive:true});rail.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();atlasSelect(e.key==='ArrowRight'?'west':'east');}});
 if(!hadSave){activateAtlasGeometry('east');reset();}else{activateAtlasGeometry(S.mapId);configureGrowth();}atlasMapCaption();save();welcome();})();

function resumeLegacyAtlas(){let raw=localStorage.getItem(atlasSaveKey(null));if(!raw)return;if(save()===false)return toast('设备存储空间不足，暂时无法安全切换存档');try{localStorage.setItem('transit-atlas-v1',raw);}catch{return toast('存档写入失败');}if(!load())return;hideAtlasMaps();closeModal();S.paused=false;atlasMapCaption();fit();save();updateUI();}

function clearAtlasTransient(){constructionUndo=null;stopUndo=null;routeGhosts=[];vehicleVisuals.clear();popEvents=[];routingBatch=null;quakeCamera=null;quakePresentation=null;selected=null;draft=null;bridgeDraft=null;gesture=null;pointers.clear();repairCenterPreview=null;meteoPreview=null;dailyReviewVisible=false;farmReviewVisible=false;lastPanelSignature='';animateView.id=(animateView.id||0)+1;$('details').hidden=true;$('undo-build').hidden=true;hideJunction();}
